content.text:
            self.cache.move_to_end(key)
            self.snapshots[request_id] = cached
            return self._publication(cached, request_id, True)
    else:
        key = None

    frozen = self._run_repair()
    if self.cache_slots > 0:
        assert key is not None
        while len(self.cache) >= self.cache_slots:
            self.cache.popitem(last=False)
        self.cache[key] = frozen
    # Snapshots are independent of later cache eviction.  FrozenRepair is
    # immutable, so sharing its tuple payload cannot alias mutable state.
    self.snapshots[request_id] = frozen
    return self._publication(frozen, request_id, False)

# ------------------------------------------------------------------
# Validation
# ------------------------------------------------------------------
def _compare(self, corrected: int, expected: int) -> bool:
    x = corrected * PPM
    y = expected * (PPM - self.bias)
    if x == y:
        return True
    return PPM * abs(x - y) <= self.tau * max(x, y)

def _handle_validate(self, event: Dict[str, Any]) -> Dict[str, Any]:
    request_id = event["id"]
    frozen = self.snapshots[request_id]
    internal_pred, external_pred = self._predictions()

    checked = 0
    passed = 0
    failed: List[str] = []
    published_by_pair = {(a, b): (value, n, d)
                         for a, b, value, n, d in frozen.links}

    for flow in self.flows:
        if flow.kind == "internal":
            if internal_pred is None:
                continue
            expected = internal_pred.get(flow.pair, 0)
        else:
            expected = external_pred[flow.pair]

        published = published_by_pair.get(flow.pair)
        if published is None:
            # With a fixed stream topology this cannot occur.
            continue
        corrected, conf_num, conf_den = published
        if conf_num * self.cutoff_den < self.cutoff_num * conf_den:
            continue

        for key in flow.report_keys:
            checked += 1
            if self._compare(corrected, expected):
                passed += 1
            else:
                failed.append(key)

    failed.sort()
    if checked == 0:
        consistent: Optional[bool] = None
    else:
        consistent = passed * self.gamma_den >= checked * self.gamma_num
    return {
        "op": "validate",
        "id": request_id,
        "checked": checked,
        "passed": passed,
        "consistent": consistent,
        "failed": failed,
    }

# ------------------------------------------------------------------
# Replay driver
# ------------------------------------------------------------------
def replay(self, events: Sequence[Dict[str, Any]],
           settings: Dict[str, Any]) -> List[Dict[str, Any]]:
    self.settings = settings
    self.trials = settings["trials"]
    self.epsilon = settings["epsilon"]
    self.seed = settings["seed"]
    cutoff = settings["cutoff"]
    self.cutoff_num, self.cutoff_den = cutoff[0], cutoff[1]
    self.bias = settings["bias"]
    self.tau = settings["tau"]
    gamma = settings["gamma"]
    self.gamma_num, self.gamma_den = gamma[0], gamma[1]
    self.cache_slots = settings["cache_slots"]

    answers: List[Dict[str, Any]] = []
    for event in events:
        op = event.get("op")
        if op == "patch":
            answers.append(self._handle_patch(event))
        elif op == "routes":
            answers.append(self._handle_routes(event))
        elif op == "repair":
            answers.append(self._handle_repair(event))
